        var es=all.SelectMany(g=>g.GetComponents<InputSystemUIInputModule>()).ToArray();if(es.Length!=1)Error(path+": EventSystem must use exactly one InputSystemUIInputModule.");
        foreach(var go in all){if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(go)>0)Error(path+": Missing Script on "+go.name);foreach(var r in go.GetComponents<Renderer>()){if(r.sharedMaterials.Any(m=>m==null))Error(path+": renderer has missing material on "+go.name);foreach(var m in r.sharedMaterials)if(m!=null&&(m.shader==null||m.shader.name.Contains("Error")))Error(path+": invalid/pink shader on "+go.name);}}
        ValidateSameSceneReferences(scene,all);
        var scaler=all.SelectMany(g=>g.GetComponents<CanvasScaler>()).FirstOrDefault();if(scaler==null||scaler.uiScaleMode!=CanvasScaler.ScaleMode.ScaleWithScreenSize)Error(path+": CanvasScaler must use Scale With Screen Size.");
        var sessions=all.SelectMany(g=>g.GetComponents<SimulationSession>()).ToArray();if(!gameplay&&sessions.Length>0)Error(path+": MainMenu must not contain SimulationSession.");if(gameplay&&final&&sessions.Length>0)Error(path+": Level02 must receive the persistent session from Level01, not define another one.");if(gameplay&&!final){if(sessions.Length!=1)Error(path+": Level01 requires exactly one SimulationSession.");else{if(sessions[0].transform.parent!=null)Error(path+": SimulationSession must be a scene-root object.");var sessionSo=new SerializedObject(sessions[0]);var iterator=sessionSo.GetIterator();while(iterator.NextVisible(true))if(iterator.propertyType==SerializedPropertyType.ObjectReference&&iterator.objectReferenceValue is Component component&&component.gameObject.scene==scene)Error(path+": SimulationSession must not serialize scene-local references.");}}
